    suspicious_cmds = ['base64', 'eval', 'wget', 'curl']
    for cmd in suspicious_cmds:
        if cmd in cmd_part:
            return True

    # Check for scripts outside standard paths
    # Extract executable/script paths from the command
    # Look for paths that aren't in /usr/bin, /bin, /sbin, /usr/sbin
    path_matches = re.findall(r'(/[^\s;|&]+)', cmd_part)
    for p in path_matches:
        p = p.rstrip(';')
        if os.path.isfile(p) or p.endswith('.sh') or p.endswith('.py') or p.endswith('.pl'):
            # Check if it's outside standard paths
            if not any(p.startswith(sp) for sp in ['/usr/bin/', '/bin/', '/sbin/', '/usr/sbin/', '/usr/bin', '/bin', '/sbin', '/usr/sbin']):
                return True

