                    if os.path.isfile(p) or p.endswith('.sh') or p.endswith('.py'):
                        return True
            # Check command paths
            parts = cmd.split()
            for part in parts:
                part = part.strip("'\"")
                if part.startswith('/') and not any(part.startswith(sp) for sp in ['/usr/bin/', '/bin/', '/sbin/', '/usr/sbin/', '/usr/bin', '/bin', '/sbin', '/usr/sbin']):
