    try:
        content = open(filepath).read()
    except:
        return False, []

    suspicious_lines = []
    for i, line in enumerate(content.splitlines(), 1):
        stripped = line.strip()
        # Skip empty lines, comments, shebang, and exit 0
        if not stripped or stripped.startswith('#') or stripped == '#!/bin/bash' or stripped == '#!/bin/sh':
            continue
