    ssh_paths = []

    # /home/*/.ssh/authorized_keys
    home_pattern = f"{base_prefix}/home/*/.ssh/authorized_keys"
    for fpath in glob.glob(home_pattern):
        if os.path.isfile(fpath):
            ssh_paths.append(os.path.realpath(fpath))

    # /root/.ssh/authorized_keys
    root_ssh = f"{base_prefix}/root/.ssh/authorized_keys"
    if os.path.isfile(root_ssh):
        ssh_paths.append(os.path.realpath(root_ssh))

    for fpath in ssh_paths:
        if not os.path.isfile(fpath):
            continue

        has_suspicious, suspicious_lines = is_suspicious_ssh_key(fpath)
        if has_suspicious:
            user = get_user_from_path(fpath)
            for line_num, line_content in suspicious_lines:
                artifacts.append({
                    "type": "ssh_key",
                    "path": fpath,
                    "sha256": sha256_file(fpath),
                    "details": {
                        "line_number": line_num,
                        "content_preview": line_content[:100],
                        "user": user
                    }
                })

    return artifacts

def main():
    all_artifacts = []

    # Scan from /app_target if it exists
    if os.path.isdir("/app_target"):
        all_artifacts.extend(scan_cron_locations("/app_target"))
        all_artifacts.extend(scan_systemd_locations("/app_target"))
        all_artifacts.extend(scan_rclocal("/app_target"))
        all_artifacts.extend(scan_ssh_keys("/app_target"))

    # Scan from root filesystem
    all_artifacts.extend(scan_cron_locations(""))
    all_artifacts.extend(scan_systemd_locations(""))
    all_artifacts.extend(scan_rclocal(""))
    all_artifacts.extend(scan_ssh_keys(""))

    # Remove duplicates based on type+path+line_number
    seen = set()
    unique_artifacts = []
    for art in all_artifacts:
        key = (art["type"], art["path"], art["details"].get("line_number"))
        if key not in seen:
            seen.add(key)
            unique_artifacts.append(art)

    # Sort by type, then by path
    unique_artifacts.sort(key=lambda x: (x["type"], x["path"], x["details"].get("line_number") or 0))

    # Build summary
    summary = {
        "total_artifacts": len(unique_artifacts),
        "cron_jobs": sum(1 for a in unique_artifacts if a["type"] == "cron_job"),
        "systemd_units": sum(1 for a in unique_artifacts if a["type"] == "systemd_unit"),
        "rc_local_modifications": sum(1 for a in unique_artifacts if a["type"] == "rc_local"),
        "ssh_keys": sum(1 for a in unique_artifacts if a["type"] == "ssh_key")
    }

    report = {
        "summary": summary,
        "artifacts": unique_artifacts
    }

    with open("/app/persistence_report.json", "w") as f:
        json.dump(report, f, indent=2)

if __name__ == "__main__":
    main()
