import os
import sys
import json
import subprocess
import re
import glob

def sha256_file(filepath):
    """Compute SHA256 hash of a file."""
    try:
        result = subprocess.run(["sha256sum", filepath], capture_output=True, text=True, timeout=10)
        if result.returncode == 0:
            return result.stdout.split()[0]
    except:
        pass
    return ""

STANDARD_PATHS = ['/usr/bin/', '/bin/', '/sbin/', '/usr/sbin/', '/usr/bin', '/bin', '/sbin', '/usr/sbin']

def is_path_nonstandard(path):
    """Check if a path is outside standard system paths."""
    return not any(path.startswith(sp) for sp in STANDARD_PATHS)

def is_suspicious_cron_line(line):
    """Check if a cron line is suspicious."""
    line = line.strip()
    if not line or line.startswith('#'):
        return False
    if re.match(r'^[A-Za-z_][A-Za-z0-9_]*=', line):
        return False

    parts = line.split()
    if len(parts) < 5:
        return False

    # Check for suspicious timing patterns (every minute, frequent intervals)
    timing_part = parts[0]
    if timing_part == '*' or re.match(r'^\*/\d+$', timing_part):
        return True

    # Get the command part
    cmd_part = ""
    if len(parts) >= 7 and not parts[5].startswith('/') and not parts[5].startswith('.') and not parts[5].startswith('$'):
        cmd_part = ' '.join(parts[6:])
    elif len(parts) >= 6:
        cmd_part = ' '.join(parts[5:])

    if not cmd_part:
        return False

    # Check for /tmp or /var/tmp references
    if '/tmp' in cmd_part or '/var/tmp' in cmd_part:
        return True

    # Check for obfuscated/suspicious commands
    for suspicious in ['base64', 'eval ', 'eval(', 'wget', 'curl']:
        if suspicious in cmd_part:
            return True

    # Check for commands/scripts outside standard paths
    path_pattern = r'(/[^\s;|&<>]+)'
    path_matches = re.findall(path_pattern, cmd_part)
    for p in path_matches:
        p_clean = p.rstrip(';')
        # If it looks like a script or is an existing file outside standard paths
        if p_clean.endswith(('.sh', '.py', '.pl', '.rb', '.bash')):
            if is_path_nonstandard(p_clean):
                return True
        elif os.path.isfile(p_clean):
            if is_path_nonstandard(p_clean):
                return True

    # Check first executable
    first_cmd = cmd_part.split()[0]
    if first_cmd.startswith('/') and is_path_nonstandard(first_cmd):
        return True

    return False

def has_suspicious_execstart(content):
    """Check if content has suspicious ExecStart commands."""
    for line in content.splitlines():
        if line.startswith('ExecStart'):
            cmd = line.split('=', 1)[1] if '=' in line else ""
            # Check for /tmp, /var/tmp
            if '/tmp' in cmd or '/var/tmp' in cmd:
                return True
            # Check for obfuscated commands
            for suspicious in ['base64', 'eval ', 'eval(', 'wget', 'curl', 'nc ', 'ncat', 'netcat']:
                if suspicious in cmd:
                    return True
            # Check for non-standard script paths
            path_pattern = r'(/[^\s;|&<>]+)'
            path_matches = re.findall(path_pattern, cmd)
            for p in path_matches:
                p_clean = p.rstrip(';')
                if p_clean.endswith(('.sh', '.py', '.pl', '.rb', '.bash')):
                    if is_path_nonstandard(p_clean):
                        return True
                elif os.path.isfile(p_clean):
                    if is_path_nonstandard(p_clean):
                        return True
            # Check command paths outside standard
            parts = cmd.split()
            for part in parts:
                part_clean = part.strip("'\"")
                if part_clean.startswith('/') and is_path_nonstandard(part_clean):
                    if os.path.isfile(part_clean) or part_clean.endswith(('.sh', '.py')):
                        return True
    return False

def is_suspicious_systemd_unit(filepath):
    """Check if a systemd unit file is suspicious."""
    basename = os.path.basename(filepath)

    # Hidden files are always suspicious
    if basename.startswith('.'):
        return True

    try:
        content = open(filepath).read()
    except:
        return False

    # Check for suspicious ExecStart commands
    if has_suspicious_execstart(content):
        return True

    # Check if not in standard package database
    try:
        result = subprocess.run(["systemctl", "list-unit-files", "--no-pager", "--no-legend"], 
                              capture_output=True, text=True, timeout=10)
        if result.returncode == 0:
            known_units = set()
            for line in result.stdout.splitlines():
                parts = line.split()
                if parts:
                    known_units.add(parts[0])
            if basename not in known_units:
                return True
    except:
        pass

    return False

def is_suspicious_rclocal(filepath):
    """Check if rc.local has suspicious modifications."""
    try:
        content = open(filepath).read()
    except:
        return False, []

    suspicious_lines = []
    for i, line in enumerate(content.splitlines(), 1):
        stripped = line.strip()
        if not stripped or stripped.startswith('#'):
            continue
        if stripped in ('#!/bin/bash', '#!/bin/sh'):
            continue
        if stripped == 'exit 0' or stripped == 'exit 1':
            continue
        suspicious_lines.append((i, stripped))

    return len(suspicious_lines) > 0, suspicious_lines

def is_suspicious_ssh_key(filepath):
    """Check SSH authorized_keys for suspicious entries."""
    try:
        content = open(filepath).read()
    except:
        return False, []

    suspicious_lines = []
    for i, line in enumerate(content.splitlines(), 1):
        stripped = line.strip()
        if not stripped or stripped.startswith('#'):
            continue
        suspicious_lines.append((i, stripped))

    return len(suspicious_lines) > 0, suspicious_lines

def get_user_from_path(filepath):
    """Extract username from authorized_keys path."""
    parts = filepath.split('/')
    if '.ssh' in parts:
        idx = parts.index('.ssh')
        if idx > 0:
            parent = parts[idx - 1]
            if parent == 'root':
                return 'root'
            return parent
    return None

def scan_cron_locations(base_prefix=""):
    """Scan cron locations for suspicious entries."""
    artifacts = []

    cron_dirs = [f"{base_prefix}/etc/cron.d/"]
    cron_files = [f"{base_prefix}/etc/crontab"]
    cron_spool = [f"{base_prefix}/var/spool/cron/crontabs/"]

    all_dirs = cron_dirs + cron_spool

    for dirpath in all_dirs:
        if not os.path.isdir(dirpath):
            continue
        try:
            for fname in os.listdir(dirpath):
                fpath = os.path.join(dirpath, fname)
                if not os.path.isfile(fpath) and not os.path.islink(fpath):
                    continue
                fpath_resolved = os.path.realpath(fpath)
                if not os.path.isfile(fpath_resolved):
                    continue
                try:
                    content = open(fpath_resolved).read()
                except:
                    continue
                for i, line in enumerate(content.splitlines(), 1):
                    if is_suspicious_cron_line(line):
                        artifacts.append({
                            "type": "cron_job",
                            "path": fpath_resolved,
                            "sha256": sha256_file(fpath_resolved),
                            "details": {
                                "line_number": i,
                                "content_preview": line[:100],
                                "user": None
                            }
                        })
        except:
            continue

    for fpath in cron_files:
        if not os.path.isfile(fpath):
            continue
        fpath_resolved = os.path.realpath(fpath)
        if not os.path.isfile(fpath_resolved):
            continue
        try:
            content = open(fpath_resolved).read()
